import{_ as s,C as c,o as t,c as o,a5 as a,b as l,w as r,a as n,E as d,a7 as p}from"./chunks/framework.QWVCgkrI.js";const k=JSON.parse('{"title":"Gitのcherry-pick — コミットではなく変更を別の履歴へ取り込む","description":"","frontmatter":{"title":"Gitのcherry-pick — コミットではなく変更を別の履歴へ取り込む","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"tools","summary":"選んだコミットが親に対して導入した変更を別の先端に適用し、新しい親・ID・ファイル内容を比較する。競合と仕様上の不整合もゲーム設定の例で区別する。","aliases":["Git cherry-pick","cherry pick","チェリーピック","修正の取り込み","バックポート"],"verification":"Git公式資料と照合し、Windowsの独立リポジトリで親・ID・ファイル内容・競合を確認（2026-11-17）"}},"headers":[],"relativePath":"tools/git-cherry-pick.md","filePath":"tools/git-cherry-pick.md"}'),E={name:"tools/git-cherry-pick.md"};function h(A,e,m,g,b,B){const i=c("Mermaid");return t(),o("div",null,[e[1]||(e[1]=a('<h1 id="gitのcherry-pick-—-コミットではなく変更を別の履歴へ取り込む" tabindex="-1">Gitのcherry-pick — コミットではなく変更を別の履歴へ取り込む <a class="header-anchor" href="#gitのcherry-pick-—-コミットではなく変更を別の履歴へ取り込む" aria-label="Permalink to &quot;Gitのcherry-pick — コミットではなく変更を別の履歴へ取り込む&quot;">​</a></h1><p>開発ブランチでは敵のHPを調整したあと、ボーナス設定も追加しました。リリース用のブランチにはHP調整だけを取り込みたいとします。<code>cherry-pick</code> は指定したコミットが導入した変更を、現在のブランチに適用します。HP調整は取り込まれますが、後から加えたボーナス設定も一緒に取り込む指定ではありません。<a href="https://git-scm.com/docs/git-cherry-pick#_description" target="_blank" rel="noreferrer">Git公式のcherry-pickマニュアル</a></p><h2 id="元の親との差を、取り込み先で組み合わせる" tabindex="-1">元の親との差を、取り込み先で組み合わせる <a class="header-anchor" href="#元の親との差を、取り込み先で組み合わせる" aria-label="Permalink to &quot;元の親との差を、取り込み先で組み合わせる&quot;">​</a></h2><p>両方のブランチはAから始まります。開発用の <code>topic</code> では、Bで敵のHPを10から20に変え、Cで <code>bonus.txt</code> を追加しました。<code>release</code> ではDでステージ番号を1から2に変えました。<code>release</code> にいる状態でBを選ぶと、GitはBとその親Aを比較し、HP調整を現在の先端Dに取り込んでEを作ります。Dにあるステージ番号2はそのままです。</p><p>図の矢印は、コミットから親へ向きます。Eの親はDです。<code>topic</code> はCを指し、Cの親は元のBのままです。</p>',5)),(t(),l(p,null,{default:r(()=>[d(i,{id:"mermaid-15",class:"mermaid",graph:"---%0Aconfig%3A%0A%20%20flowchart%3A%0A%20%20%20%20nodeSpacing%3A%2024%0A%20%20%20%20rankSpacing%3A%2032%0A%20%20%20%20padding%3A%208%0A---%0Aflowchart%20TD%0A%20%20%20%20accTitle%3A%20cherry-pick%E5%89%8D%E5%BE%8C%E3%81%AE%E9%96%8B%E7%99%BA%E3%83%96%E3%83%A9%E3%83%B3%E3%83%81%E3%81%A8%E3%83%AA%E3%83%AA%E3%83%BC%E3%82%B9%E3%83%96%E3%83%A9%E3%83%B3%E3%83%81%E3%81%AE%E8%A6%AA%E9%96%A2%E4%BF%82%0A%20%20%20%20accDescr%3A%20topic%E3%81%AFC%E3%82%92%E6%8C%87%E3%81%97%E3%80%81C%E3%81%AE%E8%A6%AA%E3%81%AFHP%E3%82%92%E5%A4%89%E6%9B%B4%E3%81%97%E3%81%9FB%E3%80%81B%E3%81%AE%E8%A6%AA%E3%81%AFA%E3%80%82release%E3%81%AFcherry-pick%E3%81%A7D%E3%81%8B%E3%82%89E%E3%81%B8%E9%80%B2%E3%81%BF%E3%80%81E%E3%81%AE%E8%A6%AA%E3%81%AFD%E3%80%81D%E3%81%AE%E8%A6%AA%E3%81%AFA%E3%80%82E%E3%81%A8B%E3%81%AF%E5%88%A5%E3%81%AE%E3%82%B3%E3%83%9F%E3%83%83%E3%83%88%E3%80%82%0A%20%20%20%20topic%5B%22topic%20%E3%81%AE%E5%85%88%E7%AB%AF%22%5D%20--%3E%20c%5B%22C%20%E3%83%9C%E3%83%BC%E3%83%8A%E3%82%B9%E8%A8%AD%E5%AE%9A%22%5D%0A%20%20%20%20c%20--%3E%7C%E8%A6%AA%7C%20b%5B%22B%20HP%E3%82%9220%E3%81%AB%22%5D%0A%20%20%20%20release%5B%22release%20%E3%81%AE%E5%85%88%E7%AB%AF%22%5D%20--%3E%20e%5B%22E%20B%E3%81%AEHP%E5%A4%89%E6%9B%B4%E3%82%92%E9%81%A9%E7%94%A8%22%5D%0A%20%20%20%20e%20--%3E%7C%E8%A6%AA%7C%20d%5B%22D%20%E3%82%B9%E3%83%86%E3%83%BC%E3%82%B8%E3%82%922%E3%81%AB%22%5D%0A%20%20%20%20b%20--%3E%7C%E8%A6%AA%7C%20a%5B%22A%20HP10%E3%83%BB%E3%82%B9%E3%83%86%E3%83%BC%E3%82%B81%22%5D%0A%20%20%20%20d%20--%3E%7C%E8%A6%AA%7C%20a%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<p>Git 2.39.2の通常の単親コミットの処理では、Aを基準としてBとDの内容を照合します。基準のAにはHP10、BにはHP20、DにはHP10があります。この行ではB側だけが変更を加えています。ステージ番号はD側だけが変えています。取り込み先が別の状態なら、照合する内容も変わります。基準にするのは選んだコミットBの親で、この例のAは共通祖先でもあります。<a href="https://github.com/git/git/blob/v2.39.2/sequencer.c#L2219-L2305" target="_blank" rel="noreferrer">Git 2.39.2のcherry-pick実装</a></p><h2 id="同じhp変更でも、親とコミットidは違う" tabindex="-1">同じHP変更でも、親とコミットIDは違う <a class="header-anchor" href="#同じhp変更でも、親とコミットidは違う" aria-label="Permalink to &quot;同じHP変更でも、親とコミットIDは違う&quot;">​</a></h2><p>コミットにはスナップショットと親のIDが記録されます。この例でBの親はA、Eの親はDです。HP変更の内容とコミットメッセージが同じでも、EはBと異なるIDを持ちます。Eにはステージ番号2も含まれるため、BとEのスナップショット全体も違います。<code>release</code> から親をたどる経路はE、D、Aで、BとCは <code>topic</code> 側の履歴に残ります。<a href="https://git-scm.com/docs/git-commit-tree#_description" target="_blank" rel="noreferrer">Git公式のcommit-treeマニュアル</a> · <a href="/study/tools/git-objects.html">Gitの保存モデル</a></p><p>次は検証用リポジトリでの実測です。<code>release</code> で <code>git cherry-pick ae44d29</code> を実行してから、元のBと適用後のEを読みました。ログはコミットの短いID、親の短いIDの順です。Eの <code>enemy.txt</code> は <code>hp=20</code>、<code>stage.txt</code> は <code>stage=2</code> で、Eのファイル一覧に <code>bonus.txt</code> はありません。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git log -1 --format=&#39;%h %p&#39; ae44d29</span></span>
<span class="line"><span>ae44d29 e723252</span></span>
<span class="line"><span>$ git log -1 --format=&#39;%h %p&#39;</span></span>
<span class="line"><span>8359b6e d12d579</span></span>
<span class="line"><span>$ git show HEAD:enemy.txt</span></span>
<span class="line"><span>hp=20</span></span>
<span class="line"><span>$ git show HEAD:stage.txt</span></span>
<span class="line"><span>stage=2</span></span>
<span class="line"><span>$ git ls-tree --name-only HEAD</span></span>
<span class="line"><span>enemy.txt</span></span>
<span class="line"><span>stage.txt</span></span></code></pre></div><h2 id="競合と、仕様上の不整合" tabindex="-1">競合と、仕様上の不整合 <a class="header-anchor" href="#競合と、仕様上の不整合" aria-label="Permalink to &quot;競合と、仕様上の不整合&quot;">​</a></h2><p>取り込み先でも同じHP行を10から30に変えていた場合、GitはHP20とHP30のどちらを使うかを自動で決められないことがあります。検証例では競合で止まり、<code>HEAD</code> は取り込み前のコミットを指し、<code>CHERRY_PICK_HEAD</code> が適用元のBを指しました。<a href="https://git-scm.com/docs/git-cherry-pick#_description" target="_blank" rel="noreferrer">Git公式のcherry-pickマニュアル</a></p><p>別の例では、取り込み先の <code>bonus.txt</code> に「HPが20以上ならボーナス対象」という条件がすでにあります。HP調整はテキストの競合なしに適用され、HPが10から20になりました。結果の設定値で条件を評価すると、対象外から対象へ変わります。ゲームの要件に合うかは、取り込み先の設定と合わせて確認する必要があります。</p><h2 id="merge・rebaseとの関係" tabindex="-1">merge・rebaseとの関係 <a class="header-anchor" href="#merge・rebaseとの関係" aria-label="Permalink to &quot;merge・rebaseとの関係&quot;">​</a></h2><ul><li><strong>cherry-pick</strong> は指定したコミットの変更を、現在の先端に取り込みます。この例ではBの変更を選び、<code>release</code> をEへ進めました。</li><li><strong>merge</strong> でこの二つの分岐を統合する場合は、それぞれの先端が出発点です。<code>topic</code> を通常の3-way mergeで取り込むなら、結果のマージコミットにはDとCを親として記録します。Cの変更も統合の対象になります。<a href="/study/tools/git-three-way-merge.html">Gitのマージ</a> · <a href="https://git-scm.com/docs/git-merge#_description" target="_blank" rel="noreferrer">Git公式のmergeマニュアル</a></li><li><strong>rebase</strong> は対象となる変更を指定した基準の上に順に再適用し、対象ブランチの先端を更新します。たとえば <code>topic</code> のBとCをDの上に載せ直すといった場面です。変更を一つずつ再適用する点はcherry-pickに似ています。<a href="/study/tools/git-rebase.html">Gitのrebase</a> · <a href="https://git-scm.com/docs/git-rebase#_description" target="_blank" rel="noreferrer">Git公式のrebaseマニュアル</a></li></ul><p>ここでのcherry-pickは、分岐した先端で単親のBを取り込む通常の実行です。<code>--ff</code> で現在の先端が選んだコミットの親と一致すれば元のコミットへ進む場合があり、<code>--no-commit</code> は変更を適用する段階で止めます。マージコミットのcherry-pickでは、<code>-m</code> が差分の基準にする親を指定します。<a href="https://git-scm.com/docs/git-cherry-pick#_options" target="_blank" rel="noreferrer">Git公式のcherry-pickオプション</a></p><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><details class="details custom-block"><summary>この例でEの親は、変更を取り込んだBになる？</summary><p>Eの親は、取り込み直前の <code>release</code> の先端Dです。Bの変更はEに反映され、元のBは <code>topic</code> 側に残ります。</p></details><details class="details custom-block"><summary>Bだけを選ぶと、Cのボーナス設定も入る？</summary><p>入りません。BがAに対して導入したのはHP調整です。<code>bonus.txt</code> はCで追加されたため、Bの変更にはありません。</p></details><details class="details custom-block"><summary>競合なしで適用できたら、HP調整の影響も元のブランチと同じ？</summary><p>取り込み先に異なるルールがあれば影響も変わります。この例では、既存のボーナス条件を満たすようになりました。</p></details><h2 id="検証範囲" tabindex="-1">検証範囲 <a class="header-anchor" href="#検証範囲" aria-label="Permalink to &quot;検証範囲&quot;">​</a></h2><p>2026年11月17日に、WindowsのGit 2.39.2.windows.1と独立したSHA-1リポジトリ3つを使いました。作業ツリーに未コミットの変更がない状態で、分岐した二つの履歴の間で単親コミットをcherry-pickしました。競合した例と、競合せずボーナス条件の結果が変わる例は別のリポジトリで確認しました。ボーナス判定は設定ファイルを読む検査です。ゲームエンジンでの動作、比較に挙げたmergeとrebase、<code>--ff</code>、<code>--no-commit</code>、マージコミットや空になる変更の取り込み、競合解消後の結果は実測範囲外です。</p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/tools/git-objects.html">Gitの保存モデル</a> — コミットのスナップショット、親、参照を確認する。</li><li><a href="/study/tools/git-three-way-merge.html">Gitのマージ</a> — 二つの先端を統合する場合の親関係をたどる。</li><li><a href="/study/tools/git-rebase.html">Gitのrebase</a> — 複数の変更を違う基準から再適用する仕組みを読む。</li><li><a href="/study/tools/git-revert.html">Gitのrevert</a> — 過去の変更を逆向きに適用する場合と比べる。</li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://git-scm.com/docs/git-cherry-pick" target="_blank" rel="noreferrer">Git公式 — git-cherry-pick</a></li><li><a href="https://github.com/git/git/blob/v2.39.2/sequencer.c#L2219-L2305" target="_blank" rel="noreferrer">Git 2.39.2 — cherry-pickとrevertの適用処理</a></li><li><a href="https://git-scm.com/docs/git-commit-tree#_description" target="_blank" rel="noreferrer">Git公式 — git-commit-tree</a></li><li><a href="https://git-scm.com/docs/git-merge#_description" target="_blank" rel="noreferrer">Git公式 — git-merge</a></li><li><a href="https://git-scm.com/docs/git-rebase#_description" target="_blank" rel="noreferrer">Git公式 — git-rebase</a></li></ul>`,21))])}const f=s(E,[["render",h]]);export{k as __pageData,f as default};
